import math
def attend(values,t,causal):
    allowed=values[:t+1] if causal else values
    scores=[values[t]*x for x in allowed]
    e=[math.exp(s-max(scores)) for s in scores]
    return sum(a*b for a,b in zip(e,allowed))/sum(e)
a=[1.0,2.0,3.0]
b=[1.0,2.0,99.0]
for causal in (True, False):
    print("因果掩码" if causal else "无掩码")
    for values in (a, b):
        print([round(attend(values, t, causal), 4) for t in range(2)])

